                    if (bun.glob.match(pattern, p).matches()) {
                        return true;
                    }
                }
            }
        }
        return false;
}

pub fn isTestFile(scanner: *Scanner, name: []const u8) bool {
        return ((scanner.couldBeTestFile(name, false) and scanner.doesPathMatchFilter(name)) and (!scanner.matchesPathIgnorePattern(name)));
}

pub fn next(scanner: *Scanner, entry: *FileSystem.Entry, fd: bun.FD) void {
        const name = entry.base_lowercase();
        scanner.has_iterated = true;
        switch (entry.kind((&scanner.fs.fs), true)) {
.dir => {
if ((((name.len > 0) and (name[0] == 46)) or strings.eqlComptime(name, "node_modules"))) {
            return;
        }
        if (comptime bun.Environment.allow_assert) {
            _ = bun.assert((!strings.contains(name, "node_modules")));
        }
        for (cp_iter_slice(scanner.exclusion_names)) |exclude_name| {
            _ = &exclude_name;
            if (strings.eql(exclude_name, name)) {
                return;
            }
        }
        if ((scanner.path_ignore_patterns.len > 0)) {
            const parts: [2][]const u8 = .{ entry.dir, entry.base() };
            const dir_path = scanner.fs.absBuf((&parts), (&scanner.open_dir_buf));
            if (scanner.matchesPathIgnorePattern(dir_path)) {
                return;
            }
        }
        scanner.search_count = (scanner.search_count + 1);
        _ = ((scanner.dirs_to_scan.writeItem(ScanEntry{ .relative_dir = fd, .name = entry.base_, .dir_path = entry.dir })) catch unreachable);
},
.file => {
if ((!entry.abs_path.isEmpty())) {
            return;
        }
        scanner.search_count = (scanner.search_count + 1);
        if ((!scanner.couldBeTestFile(name, true))) {
            return;
        }
        const parts: [2][]const u8 = .{ entry.dir, entry.base() };
        const path = scanner.fs.absBuf((&parts), (&scanner.open_dir_buf));
        if ((!scanner.doesAbsolutePathMatchFilter(path))) {
            const rel_path = bun.path.relative(scanner.fs.top_level_dir, path);
            if ((!scanner.doesPathMatchFilter(rel_path))) {
                return;
            }
        }
        if (scanner.matchesPathIgnorePattern(path)) {
            return;
        }
        entry.abs_path = bun.PathString.init(((scanner.fs.filename_store.append(@TypeOf(path), path)) catch unreachable));
        _ = ((scanner.test_files.append(scanner.allocator(), entry.abs_path)) catch unreachable);
},
}
}

pub inline fn allocator(scanner: *const Scanner) Allocator {
        return scanner.dirs_to_scan.allocator;
}
